function Read-JsonUtf8([string]$Path) { Get-Content -LiteralPath $Path -Raw -Encoding UTF8 | ConvertFrom-Json }
function Write-JsonUtf8([string]$Path, [object]$Value) { ($Value | ConvertTo-Json -Depth 24) | Set-Content -LiteralPath $Path -Encoding UTF8 }
function Get-Hash([string]$Path) { (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToUpperInvariant() }
function ConvertTo-HexString([byte[]]$Bytes) { ([BitConverter]::ToString($Bytes)).Replace('-', '').ToUpperInvariant() }
function Get-OleSignature([string]$Path) {
    $stream = [IO.File]::Open($Path, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::ReadWrite)
    try { $bytes = New-Object byte[] 8; if ($stream.Read($bytes,0,8) -ne 8) { return '' }; ConvertTo-HexString $bytes } finally { $stream.Dispose() }
}
function Get-WordIds { @(Get-Process -Name WINWORD -ErrorAction SilentlyContinue | Select-Object -ExpandProperty Id) }
function Get-NewIds([int[]]$Before) { @(Get-WordIds | Where-Object { $Before -notcontains $_ }) }
function Release-Com([object]$Object) { try { if ($null -ne $Object -and [Runtime.InteropServices.Marshal]::IsComObject($Object)) { [void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($Object) }; $true } catch { $false } }
function Wait-ForStageProcessExit([int[]]$Ids) {
    $deadline = (Get-Date).AddMilliseconds(30000)
    do { $remaining = @(Get-WordIds | Where-Object { $Ids -contains $_ }); if ($remaining.Count -eq 0) { return [pscustomobject]@{ exited=1; remaining=@() } }; Start-Sleep -Milliseconds 250 } while ((Get-Date) -lt $deadline)
    [pscustomobject]@{ exited=0; remaining=@(Get-WordIds | Where-Object { $Ids -contains $_ }) }
}
function Get-WordProductVersion { if (-not (Test-Path -LiteralPath $WordExecutable -PathType Leaf)) { return '' }; [string](Get-Item -LiteralPath $WordExecutable).VersionInfo.FileVersion }
function Set-Primary([object]$State,[string]$Code,[string]$Message) { if ([string]::IsNullOrWhiteSpace($State.primary_error_code)) { $State.primary_error_code=$Code; $State.primary_error_message=$Message } }
function Set-Cleanup([object]$State,[string]$Code,[string]$Message) { if ([string]::IsNullOrWhiteSpace($State.cleanup_error_code)) { $State.cleanup_error_code=$Code; $State.cleanup_error_message=$Message } }
function Read-Diagnostics([object]$State,[object]$Doc) {
    foreach($pair in @(@('words_count','Words'),@('characters_count','Characters'),@('paragraphs_count','Paragraphs'),@('sections_count','Sections'),@('tables_count','Tables'),@('inline_shapes_count','InlineShapes'),@('shapes_count','Shapes'),@('fields_count','Fields'))) {
        $item=$null; try { $item=$Doc.($pair[1]); $State.($pair[0])=[int]$item.Count } catch { $State.diagnostic_errors += "$($pair[1]):$($_.Exception.Message)" } finally { if($item){[void](Release-Com $item)} }
    }
    try {$State.compatibility_mode=[int]$Doc.CompatibilityMode} catch {}
    try {$State.protection_type=[int]$Doc.ProtectionType} catch {}
}
function Test-DocxBasic([string]$Path) {
    $state=[ordered]@{exists=0;size=0;sha256='';zip_signature_valid=0;zip_readable=0;content_types=0;document_xml=0;rels=0;document_rels=0;pass=0;error=''}
    if(-not(Test-Path -LiteralPath $Path -PathType Leaf)){ $state.error='missing'; return [pscustomobject]$state }
    $state.exists=1;$state.size=(Get-Item -LiteralPath $Path).Length;$state.sha256=Get-Hash $Path
    $head=[IO.File]::ReadAllBytes($Path); if($head.Length -ge 4 -and [Text.Encoding]::ASCII.GetString($head,0,2) -eq 'PK'){$state.zip_signature_valid=1}else{$state.error='invalid_zip_signature';return [pscustomobject]$state}
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    try {$zip=[IO.Compression.ZipFile]::OpenRead($Path);$names=@($zip.Entries|ForEach-Object{$_.FullName});$state.zip_readable=1;$state.content_types=[int]($names -contains '[Content_Types].xml');$state.document_xml=[int]($names -contains 'word/document.xml');$state.rels=[int]($names -contains '_rels/.rels');$state.document_rels=[int]($names -contains 'word/_rels/document.xml.rels')}catch{$state.error=$_.Exception.Message}finally{if($zip){$zip.Dispose()}}
    $state.pass=[int]($state.size -gt 0 -and $state.zip_signature_valid -eq 1 -and $state.zip_readable -eq 1 -and $state.content_types -eq 1 -and $state.document_xml -eq 1);[pscustomobject]$state
}
function Test-PdfBasic([string]$Path) {
    $state=[ordered]@{exists=0;size=0;sha256='';signature_valid=0;readable=0;page_count=0;error=''};if(-not(Test-Path -LiteralPath $Path -PathType Leaf)){ $state.error='missing';return [pscustomobject]$state};$state.exists=1;$state.size=(Get-Item -LiteralPath $Path).Length;$state.sha256=Get-Hash $Path
    $head=[IO.File]::ReadAllBytes($Path);$state.signature_valid=[int]($head.Length -ge 4 -and [Text.Encoding]::ASCII.GetString($head,0,4) -eq '%PDF');if($state.signature_valid -ne 1){$state.error='invalid_signature';return [pscustomobject]$state};$info=Get-Command pdfinfo.exe -ErrorAction SilentlyContinue;if($null -eq $info){$state.error='pdfinfo_unavailable';return [pscustomobject]$state};$lines=& $info.Source $Path 2>&1;if($LASTEXITCODE -ne 0){$state.error='pdfinfo_failed';return [pscustomobject]$state};foreach($line in $lines){if([string]$line -match '^Pages:\s*(\d+)'){$state.page_count=[int]$Matches[1]}};$state.readable=[int]($state.page_count -gt 0);$state.pass=[int]($state.size -gt 0 -and $state.signature_valid -eq 1 -and $state.readable -eq 1);[pscustomobject]$state
}
function Invoke-WordSession([string]$Name,[string]$InputPath,[string]$OutputPath,[ValidateSet('DOC_TO_DOCX','DOCX_TO_PDF')][string]$Route) {
    $state=[ordered]@{session=$Name;route=$Route;word_create_attempted=0;word_created=0;word_com_version='';word_product_version='';version_gate_pass=0;security_configured=0;document_open_attempted=0;document_opened=0;read_only=0;save_attempted=0;save_completed=0;export_attempted=0;export_returned=0;export_completed=0;document_close_attempted=0;document_closed=0;word_quit_attempted=0;word_quit_called=0;com_references_released=0;word_process_exited=0;stage_word_pid='';input_sha_before='';input_sha_after='';input_mutation_detected=0;words_count=$null;characters_count=$null;paragraphs_count=$null;sections_count=$null;tables_count=$null;inline_shapes_count=$null;shapes_count=$null;fields_count=$null;compatibility_mode=$null;protection_type=$null;diagnostic_errors=@();primary_error_code='';primary_error_message='';cleanup_error_code='';cleanup_error_message='';output_basic_pass=0;output_sha256=''}
    if(Test-Path -LiteralPath $OutputPath -PathType Leaf){Set-Primary $state 'ISOLATED_OUTPUT_ALREADY_EXISTS' $OutputPath;return [pscustomobject]$state};$word=$null;$docs=$null;$doc=$null;$options=$null;$before=Get-WordIds;$new=@();$released=$true;$missing=[Type]::Missing
    try {$state.word_create_attempted=1;$word=New-Object -ComObject Word.Application;$state.word_created=1;$new=Get-NewIds $before;$state.stage_word_pid=$new -join ',';$script:StageIds += $new;if($new.Count -ne 1){throw 'PROCESS_OWNERSHIP_AMBIGUOUS'};$state.word_com_version=[string]$word.Version;$state.word_product_version=Get-WordProductVersion;if($state.word_com_version -ne $ExpectedComVersion -or $state.word_product_version -ne $ExpectedProductVersion){throw 'CANDIDATE_VERSION_DRIFT_DURING_PILOT'};$state.version_gate_pass=1;$word.Visible=$false;$word.DisplayAlerts=0;$word.AutomationSecurity=3;$options=$word.Options;$options.UpdateLinksAtOpen=$false;$options.ConfirmConversions=$false;$options.SavePropertiesPrompt=$false;$state.security_configured=1;$docs=$word.Documents;$state.document_open_attempted=1;$doc=$docs.Open($InputPath,$false,$true,$false,$missing,$missing,$false,$missing,$missing,$missing,$missing,$false,$false);if($null -eq $doc -or $doc.ReadOnly -ne $true){throw 'READ_ONLY_OPEN_FAILED'};$state.document_opened=1;$state.read_only=1;$state.input_sha_before=Get-Hash $InputPath;Read-Diagnostics $state $doc
        if($Route -eq 'DOC_TO_DOCX'){
            $state.save_attempted=1;New-Item -ItemType Directory -Force -Path (Split-Path -Parent $OutputPath)|Out-Null;[void]$doc.SaveAs2($OutputPath,[int]16);$state.save_completed=1
            # DOCX ZIP/SHA validation is intentionally deferred until this
            # session's document close, Word.Quit, COM release and PID exit.
        }else{$state.export_attempted=1;New-Item -ItemType Directory -Force -Path (Split-Path -Parent $OutputPath)|Out-Null;[void]$doc.ExportAsFixedFormat($OutputPath,[int]17);$state.export_returned=1;$basic=Test-PdfBasic $OutputPath;$state.export_completed=[int]($basic.pass -eq 1);$state.output_basic_pass=$basic.pass;$state.output_sha256=$basic.sha256;if($basic.pass -ne 1){throw 'OUTPUT_BASIC_VALIDATION_FAILED'}}
    }catch{$msg=$_.Exception.Message;if($state.word_created -eq 0){Set-Primary $state 'WORD_CREATE_ERROR' $msg}elseif($state.version_gate_pass -eq 0){Set-Primary $state 'VERSION_GATE_ERROR' $msg}elseif($state.document_opened -eq 0){Set-Primary $state 'DOCUMENT_OPEN_ERROR' $msg}elseif($Route -eq 'DOC_TO_DOCX' -and $state.save_completed -eq 0){Set-Primary $state 'DOC_TO_DOCX_SAVE_FAILED' $msg}elseif($Route -eq 'DOCX_TO_PDF' -and $state.export_returned -eq 0){Set-Primary $state 'DOCX_TO_PDF_EXPORT_FAILED' $msg}else{Set-Primary $state 'OUTPUT_VALIDATION_ERROR' $msg}}
    finally{if($doc){$state.document_close_attempted=1;try{$doc.Close($false);$state.document_closed=1}catch{Set-Cleanup $state 'DOCUMENT_CLOSE_ERROR' $_.Exception.Message};if(-not(Release-Com $doc)){$released=$false};$doc=$null};if($options){if(-not(Release-Com $options)){$released=$false};$options=$null};if($docs){if(-not(Release-Com $docs)){$released=$false};$docs=$null};if($word){$state.word_quit_attempted=1;try{$word.Quit();$state.word_quit_called=1}catch{Set-Cleanup $state 'WORD_QUIT_ERROR' $_.Exception.Message};if(-not(Release-Com $word)){$released=$false};$word=$null};$state.com_references_released=[int]$released;[GC]::Collect();[GC]::WaitForPendingFinalizers();[GC]::Collect();[GC]::WaitForPendingFinalizers();$exit=Wait-ForStageProcessExit $new;$state.word_process_exited=$exit.exited;if($exit.exited -eq 1){$script:CleanedCount += $new.Count}else{$script:OrphanIds += $exit.remaining;Set-Cleanup $state 'ORPHAN_STAGE_WORD_PROCESS' ($exit.remaining -join ',')};if(Test-Path -LiteralPath $InputPath -PathType Leaf){$state.input_sha_after=Get-Hash $InputPath;$state.input_mutation_detected=[int]($state.input_sha_before -ne '' -and $state.input_sha_before -ne $state.input_sha_after)}}
    if($state.primary_error_code){$state.error_code=$state.primary_error_code}else{$state.error_code=$state.cleanup_error_code};[pscustomobject]$state
}

$result=[ordered]@{STAGE='G8-DOC-CUMCM-2012-D-001-DOCX-INTERMEDIATE-PILOT';STATUS='BLOCKED';TARGET_PAPER_ID=$TargetPaperId;WORD_COM_RUN=0;DOC_CONVERSION_RUN=0}
try {$manifest=Read-JsonUtf8 $ManifestPath;$contract=Read-JsonUtf8 $ContractPath;$decision=Read-JsonUtf8 $DecisionPath
    $prior=if(Test-Path -LiteralPath $ResultPath -PathType Leaf){Read-JsonUtf8 $ResultPath}else{$null}
    if($null -ne $prior -and $prior.DOCX_SAVE_ATTEMPT_COUNT -ge 1 -and $prior.DOCX_PDF_EXPORT_ATTEMPT_COUNT -ge 1){$guard=[ordered]@{STAGE='G8-DOC-CUMCM-2012-D-001-DOCX-INTERMEDIATE-PILOT';STATUS='BLOCKED';TARGET_PAPER_ID=$TargetPaperId;DOCX_INTERMEDIATE_PILOT_ALREADY_EXHAUSTED=1;DOCX_INTERMEDIATE_PILOT_EXHAUSTED=1;WORD_COM_RUN=0;DOC_CONVERSION_RUN=0;BLOCKER='DOCX_INTERMEDIATE_PILOT_ALREADY_EXHAUSTED'};Write-Output($guard|ConvertTo-Json -Compress);exit 2}
    $source=$manifest.source_absolute;$sourceSha=Get-Hash $source;$sourceSize=(Get-Item -LiteralPath $source).Length;$sourceOle=Get-OleSignature $source;$preflight=[int]($sourceSha -eq $ExpectedSha -and $sourceSize -eq $ExpectedSize -and $sourceOle -eq $ExpectedOle);if($contract.active_converter_version -ne $ExpectedProductVersion -or $contract.validated_converter_versions -notcontains $ExpectedProductVersion){throw 'ACTIVE_CONVERTER_CONTRACT_UNEXPECTED'};if($decision.targeted_repair_exhausted -ne 1 -or $decision.direct_word_export_route_status -ne 'CLOSED'){throw 'DIRECT_EXPORT_ROUTE_NOT_CLOSED'};if($preflight -ne 1){throw 'SOURCE_PREFLIGHT_ERROR'};$s1=Invoke-WordSession 'SESSION_1' $source $manifest.docx_output_path 'DOC_TO_DOCX';$docx=Test-DocxBasic $manifest.docx_output_path;$s2=$null;if($s1.save_completed -eq 1 -and $docx.pass -eq 1 -and $s1.input_mutation_detected -eq 0 -and $script:OrphanIds.Count -eq 0){$s2=Invoke-WordSession 'SESSION_2' $manifest.docx_output_path $manifest.pdf_output_path 'DOCX_TO_PDF'};$pdf=Test-PdfBasic $manifest.pdf_output_path;$catastrophic=[int]($null -ne $s2 -and (($s2.paragraphs_count -eq 0) -or ($s2.inline_shapes_count -eq 0) -or ($s2.tables_count -eq 0)));$ok=[int]($s1.save_completed -eq 1 -and $docx.pass -eq 1 -and $null -ne $s2 -and $s2.export_completed -eq 1 -and $pdf.pass -eq 1 -and $s1.input_mutation_detected -eq 0 -and $s2.input_mutation_detected -eq 0 -and $catastrophic -eq 0 -and $script:OrphanIds.Count -eq 0);$result=[ordered]@{STAGE='G8-DOC-CUMCM-2012-D-001-DOCX-INTERMEDIATE-PILOT';STATUS=if($ok){'PASS'}else{'PARTIAL'};TARGET_PAPER_ID=$TargetPaperId;SOURCE_SHA256=$sourceSha;SOURCE_SIZE=$sourceSize;SOURCE_OLE_SIGNATURE=$sourceOle;SOURCE_PREFLIGHT_PASS=$preflight;DOCX_OUTPUT_PATH=$manifest.docx_output_path;PDF_OUTPUT_PATH=$manifest.pdf_output_path;SESSION_1=$s1;SESSION_2=$s2;DOCX_BASIC_VALIDATION=$docx;PDF_BASIC_VALIDATION=$pdf;DOCX_SAVE_ATTEMPT_COUNT=1;DOCX_SAVE_SUCCESS_COUNT=[int]($s1.save_completed -eq 1);DOCX_PDF_EXPORT_ATTEMPT_COUNT=if($null -ne $s2){$s2.export_attempted}else{0};DOCX_PDF_EXPORT_SUCCESS_COUNT=if($null -ne $s2){$s2.export_completed}else{0};DOCX_SHA_MUTATION_DETECTED=if($null -ne $s2){$s2.input_mutation_detected}else{0};SOURCE_SHA_MISMATCH=[int]($sourceSha -ne $ExpectedSha);SOURCE_MUTATION_DETECTED=$s1.input_mutation_detected;ORIGINAL_FILES_MODIFIED=0;STRUCTURAL_CATASTROPHIC_LOSS=$catastrophic;STAGE_WORD_SESSION_COUNT=@($s1,$s2|Where-Object{$null -ne $_ -and $_.word_created -eq 1}).Count;STAGE_WORD_PROCESS_COUNT_CREATED=@($script:StageIds|Select-Object -Unique).Count;STAGE_WORD_PROCESS_COUNT_CLEANED=$script:CleanedCount;STAGE_WORD_ORPHAN_COUNT=@($script:OrphanIds|Select-Object -Unique).Count;SESSION_1_WORD_PID=$s1.stage_word_pid;SESSION_2_WORD_PID=if($null -ne $s2){$s2.stage_word_pid}else{''};REMEDIATION_CANDIDATE_AVAILABLE=$ok;WORD_COM_RUN=@($s1,$s2|Where-Object{$null -ne $_ -and $_.word_created -eq 1}).Count;DOC_CONVERSION_RUN=if($null -ne $s2){$s2.export_attempted}else{0};TARGETED_EXPORT_ATTEMPT_COUNT=2;TARGETED_EXPORT_FAILURE_COUNT=2;TARGETED_REPAIR_EXHAUSTED=1;DIRECT_WORD_EXPORT_ROUTE_STATUS='CLOSED';NEXT=if($ok){'G8-DOC-CUMCM-2012-D-001-DOCX-INTERMEDIATE-QA'}else{'G8-DOC-CUMCM-2012-D-001-REACQUISITION-DECISION'}}}catch{$result.STATUS='BLOCKED';$result.BLOCKER=$_.Exception.Message}finally{Write-JsonUtf8 $ResultPath $result;Write-Output($result|ConvertTo-Json -Depth 24 -Compress);if($result.STATUS -eq 'BLOCKED'){exit 2}}
